/** Decode base64 kecil (ilustrasi maintenance) menjadi byte untuk direspons. */
function muatB64(b64) {
  const bin = atob(b64);
  const u = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
  return u;
}

