const _rateMem = new Map();
function rateMem(key, max, windowSec) {
  const now = Date.now() / 1000;
  let arr = _rateMem.get(key) || [];
  arr = arr.filter((t) => t > now - windowSec);
  if (arr.length >= max) return false;
  arr.push(now);
  _rateMem.set(key, arr);
  return true;
}
