          const b = await req.json().catch(() => ({}));
          const kunci = String(b.kunci || '').trim();
          if (!/^[a-z0-9_.-]{1,64}$/.test(kunci)) return err('Nama kunci tidak valid', 400, env);
          await simpanSetelan(env, kunci, b.nilai ?? '');
